const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const mountFuji = ee.Geometry.Point(138.7289, 35.3606);
    const startDate2020 = '2020-12-01';
    const endDate2020 = '2020-12-31';
    const yearsToCompare = Array.from({ length: 11 }, (_, i) => 2005 + i); // 2005-2015

    // Function to mask clouds in Landsat 8 SR imagery
    function maskL8sr(image) {
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudShadowBitMask = (1 << 3);
      const cloudsBitMask = (1 << 5);
      // Get the QA band.
      const qa = image.select('pixel_qa');
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
        .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      // Return the masked image with a valid range of values.
      return image.updateMask(mask).select(['B2', 'B3', 'B5', 'B6', 'B7', 'B10'])
        .copyProperties(image, ['system:time_start']);
    }

    // Function to mask clouds in Landsat 7 SR imagery
    function maskL7sr(image) {
      const qa = image.select('pixel_qa');
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudShadowBitMask = (1 << 3);
      const cloudsBitMask = (1 << 5);
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
        .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

      // Apply the mask and select relevant bands.
      return image.updateMask(mask)
        .select(['B1', 'B2', 'B4', 'B5', 'B7']) // B2=Green, B5=SWIR1
        .copyProperties(image, ['system:time_start']);
    }

    // Function to calculate NDSI
    function addNdsi(image, sensor) {
      let greenBand, swir1Band;
      if (sensor === 'L8') {
        greenBand = 'B3'; // Landsat 8 Green
        swir1Band = 'B6'; // Landsat 8 SWIR1
      } else if (sensor === 'L7') {
        greenBand = 'B2'; // Landsat 7 Green
        swir1Band = 'B5'; // Landsat 7 SWIR1
      } else {
        return image; // Should not happen if called correctly
      }

      const ndsi = image.normalizedDifference([greenBand, swir1Band]).rename('NDSI');
      return image.addBands(ndsi);
    }

    // Function to get NDSI for a given year using L8 or L7
    async function getMeanNdsiForYear(year, geometry) {
      const yearStart = `${year}-12-01`;
      const yearEnd = `${year}-12-31`;

      let collection = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
        .filterDate(yearStart, yearEnd)
        .filterBounds(geometry)
        .map(maskL8sr)
        .map(img => addNdsi(img, 'L8'));

      const l8_size = await collection.size().getInfo();
      let sensorUsed = 'L8';

      if (l8_size === 0 || year < 2013) { // Landsat 8 started in 2013, so for earlier years or if L8 is empty
        collection = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR')
          .filterDate(yearStart, yearEnd)
          .filterBounds(geometry)
          .map(maskL7sr)
          .map(img => addNdsi(img, 'L7'));
        sensorUsed = 'L7';
      }

      const collectionSize = await collection.size().getInfo();
      if (collectionSize === 0) {
        return { year: year, ndsi: null, count: 0, sensor: sensorUsed, images: 0 };
      }

      const composite = collection.mean().select('NDSI');
      if (!composite) { // Check if mean composite is null
        return { year: year, ndsi: null, count: 0, sensor: sensorUsed, images: collectionSize };
      }

      const stats = await composite.reduceRegion({
        reducer: ee.Reducer.mean().combine({
          reducer2: ee.Reducer.count(),
          sharedInputs: true
        }),
        geometry: geometry,
        scale: 30, // Using 30m as the base Landsat resolution
        maxPixels: 1e9
      }).getInfo();

      const meanNdsi = stats && stats.NDSI !== undefined ? stats.NDSI : null;
      const pixelCount = stats && stats.count !== undefined ? stats.count : 0;

      return { year: year, ndsi: meanNdsi, count: pixelCount, sensor: sensorUsed, images: collectionSize };
    }

    // 2. Data Acquisition & Check for 2020
    const result2020 = await getMeanNdsiForYear(2020, mountFuji);
    console.log(`2020 Images: ${result2020.images} (${result2020.sensor})`);

    if (result2020.images === 0) {
      console.log("No data found for 2020.");
      console.log("C1");
      return;
    }
    if (result2020.count === 0) {
      console.log("No valid pixels for 2020 after masking.");
      console.log("C2");
      return;
    }
    if (result2020.ndsi === null || isNaN(result2020.ndsi)) {
      console.log("2020 NDSI calculation failed.");
      console.log("C3");
      return;
    }
    console.log(`2020 Mean NDSI: ${result2020.ndsi.toFixed(4)} (Pixels: ${result2020.count})`);

    // 3. Data Acquisition & Check for 2005-2015
    const comparisonResults = [];
    for (const year of yearsToCompare) {
      const result = await getMeanNdsiForYear(year, mountFuji);
      console.log(`${year} Images: ${result.images} (${result.sensor})`);
      comparisonResults.push(result);
    }

    // Filter out years with no data or invalid pixels for comparison
    const validComparisonResults = comparisonResults.filter(r => r.images > 0 && r.count > 0 && r.ndsi !== null && !isNaN(r.ndsi));

    if (validComparisonResults.length === 0) {
      console.log("No valid comparison data from 2005-2015 after filtering.");
      console.log("C1"); // No valid comparison years
      return;
    }

    // 4. Calculation & Comparison
    let lowestNdsiInComparisonPeriod = Infinity;
    let lowestYear = null;

    for (const res of validComparisonResults) {
      console.log(`${res.year} Mean NDSI: ${res.ndsi.toFixed(4)} (Pixels: ${res.count})`);
      if (res.ndsi < lowestNdsiInComparisonPeriod) {
        lowestNdsiInComparisonPeriod = res.ndsi;
        lowestYear = res.year;
      }
    }

    if (lowestNdsiInComparisonPeriod === Infinity) {
      console.log("No valid NDSI values found for comparison period.");
      console.log("C3");
      return;
    }

    console.log(`Lowest NDSI (2005-2015): ${lowestNdsiInComparisonPeriod.toFixed(4)} (in ${lowestYear})`);

    // 5. Validation & Final Answer
    const is2020Lower = result2020.ndsi < lowestNdsiInComparisonPeriod;

    if (is2020Lower) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log("D"); // Catch any unexpected errors like method errors or memory issues
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

